INSERT INTO `code_challenges` VALUES (10,NULL,1,'Custom Code & GUI Sandbox','custom-sandbox','Easy','General','Free interactive execution sandbox. Run arbitrary HTML/CSS/JavaScript with live GUI rendering, or execute Python, Java, and SQL scripts.','Standard Input / CLI arguments','Standard Output / Interactive GUI preview','Max Execution Time: 5s\nMemory Limit: 128MB','public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Hello from Java Sandbox!\");\n    }\n}','# Python Interactive Sandbox\ndef solve():\n    print(\"Hello from Python Sandbox!\")\n\nsolve()','// JavaScript / Interactive GUI Sandbox\nconsole.log(\"Hello from JavaScript Sandbox!\");','#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Hello from C++ Sandbox!\" << endl;\n    return 0;\n}','-- SQL Query Scratchpad\nSELECT id, title, price FROM courses LIMIT 5;','[]',10,1,'2026-08-21 21:08:02'),(11,NULL,1,'Two Sum Problem','two-sum','Easy','Arrays & Hashing','Given an array of integers nums and an integer target, return indices of the two numbers such that they add up to target.\n\nYou may assume that each input would have exactly one solution, and you may not use the same element twice.','[2,7,11,15]\n9','[0,1]','2 <= nums.length <= 10^4\n-10^9 <= nums[i] <= 10^9\nTime Complexity Goal: O(N)\nSpace Complexity Goal: O(N)','import java.util.*;\n\npublic class Solution {\n    public static int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> map = new HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            int complement = target - nums[i];\n            if (map.containsKey(complement)) {\n                return new int[]{map.get(complement), i};\n            }\n            map.put(nums[i], i);\n        }\n        return new int[]{};\n    }\n}','import sys, json\n\ndef two_sum(nums, target):\n    seen = {}\n    for i, num in enumerate(nums):\n        comp = target - num\n        if comp in seen:\n            return [seen[comp], i]\n        seen[num] = i\n    return []\n\nif __name__ == \'__main__\':\n    lines = sys.stdin.read().strip().splitlines()\n    if len(lines) >= 2:\n        nums = json.loads(lines[0])\n        target = int(lines[1])\n        print(json.dumps(two_sum(nums, target)))','function twoSum(nums, target) {\n    const map = new Map();\n    for (let i = 0; i < nums.length; i++) {\n        const comp = target - nums[i];\n        if (map.has(comp)) {\n            return [map.get(comp), i];\n        }\n        map.set(nums[i], i);\n    }\n    return [];\n}\n\nconst fs = require(\'fs\');\nconst input = fs.readFileSync(0, \'utf-8\').trim().split(\'\\n\');\nif (input.length >= 2) {\n    console.log(JSON.stringify(twoSum(JSON.parse(input[0]), parseInt(input[1]))));\n}','#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> twoSum(vector<int>& nums, int target) {\n        unordered_map<int, int> m;\n        for (int i = 0; i < nums.size(); i++) {\n            int comp = target - nums[i];\n            if (m.count(comp)) return {m[comp], i};\n            m[nums[i]] = i;\n        }\n        return {};\n    }\n};','','[{\"input\":\"[2,7,11,15]\\n9\",\"expected_output\":\"[0,1]\",\"is_hidden\":false},{\"input\":\"[3,2,4]\\n6\",\"expected_output\":\"[1,2]\",\"is_hidden\":false},{\"input\":\"[3,3]\\n6\",\"expected_output\":\"[0,1]\",\"is_hidden\":false}]',50,1,'2026-08-21 21:08:02'),(12,NULL,1,'Valid Parentheses','valid-parentheses','Easy','Stack','Given a string s containing just the characters \'(\', \')\', \'{\', \'}\', \'[\' and \']\', determine if the input string is valid.\n\nAn input string is valid if open brackets are closed by the same type of brackets and in the correct order.','()[]{}','true','1 <= s.length <= 10^4\ns consists of parentheses only \'()[]{}\'.','import java.util.*;\n\npublic class Solution {\n    public static boolean isValid(String s) {\n        Stack<Character> stack = new Stack<>();\n        for (char c : s.toCharArray()) {\n            if (c == \'(\') stack.push(\')\');\n            else if (c == \'{\') stack.push(\'}\');\n            else if (c == \'[\') stack.push(\']\');\n            else if (stack.isEmpty() || stack.pop() != c) return false;\n        }\n        return stack.isEmpty();\n    }\n}','import sys\n\ndef is_valid(s: str) -> bool:\n    stack = []\n    mapping = {\')\': \'(\', \'}\': \'{\', \']\': \'[\'}\n    for char in s:\n        if char in mapping:\n            if not stack or stack.pop() != mapping[char]:\n                return False\n        else:\n            stack.append(char)\n    return len(stack) == 0\n\nif __name__ == \'__main__\':\n    print(\'true\' if is_valid(sys.stdin.read().strip()) else \'false\')','function isValid(s) {\n    const stack = [];\n    const map = { \')\': \'(\', \'}\': \'{\', \']\': \'[\' };\n    for (const char of s) {\n        if (char in map) {\n            if (stack.pop() !== map[char]) return false;\n        } else {\n            stack.push(char);\n        }\n    }\n    return stack.length === 0;\n}\n\nconst fs = require(\'fs\');\nconsole.log(isValid(fs.readFileSync(0, \'utf-8\').trim()) ? \'true\' : \'false\');','','','[{\"input\":\"()\",\"expected_output\":\"true\",\"is_hidden\":false},{\"input\":\"()[]{}\",\"expected_output\":\"true\",\"is_hidden\":false},{\"input\":\"(]\",\"expected_output\":\"false\",\"is_hidden\":false}]',50,1,'2026-08-21 21:08:02'),(13,NULL,1,'Reverse Integer','reverse-integer','Medium','Math','Given a signed 32-bit integer x, return x with its digits reversed. If reversing x causes the value to go outside the signed 32-bit integer range [-2^31, 2^31 - 1], return 0.','123','321','-2^31 <= x <= 2^31 - 1','public class Solution {\n    public static int reverse(int x) {\n        int rev = 0;\n        while (x != 0) {\n            int pop = x % 10;\n            x /= 10;\n            if (rev > Integer.MAX_VALUE/10 || (rev == Integer.MAX_VALUE / 10 && pop > 7)) return 0;\n            if (rev < Integer.MIN_VALUE/10 || (rev == Integer.MIN_VALUE / 10 && pop < -8)) return 0;\n            rev = rev * 10 + pop;\n        }\n        return rev;\n    }\n}','import sys\n\ndef reverse(x: int) -> int:\n    sign = -1 if x < 0 else 1\n    rev = int(str(abs(x))[::-1]) * sign\n    if rev < -2**31 or rev > 2**31 - 1:\n        return 0\n    return rev\n\nif __name__ == \'__main__\':\n    print(reverse(int(sys.stdin.read().strip())))','function reverse(x) {\n    const sign = x < 0 ? -1 : 1;\n    const rev = parseInt(Math.abs(x).toString().split(\'\').reverse().join(\'\')) * sign;\n    if (rev < -(2**31) || rev > (2**31 - 1)) return 0;\n    return rev;\n}\n\nconst fs = require(\'fs\');\nconsole.log(reverse(parseInt(fs.readFileSync(0, \'utf-8\').trim())));','','','[{\"input\":\"123\",\"expected_output\":\"321\",\"is_hidden\":false},{\"input\":\"-123\",\"expected_output\":\"-321\",\"is_hidden\":false},{\"input\":\"120\",\"expected_output\":\"21\",\"is_hidden\":false}]',75,1,'2026-08-21 21:08:02');
