igh = arr.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (arr[mid] == target) return mid;\n            if (arr[mid] < target) low = mid + 1;\n            else high = mid - 1;\n        }\n        return -1;\n    }\n}','public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"=========================================\");\n        System.out.println(\" ☕ JAVA 21 PRO STUDIO — EDUCATION ALGORITHM\");\n        System.out.println(\"=========================================\");\n        \n        // 1. Array Processing\n        int[] numbers = {15, 30, 45, 60, 75};\n        int sum = 0;\n        for (int num : numbers) {\n            sum += num;\n        }\n        System.out.println(\"✓ Array Elements Sum: \" + sum);\n        System.out.println(\"✓ Average Value: \" + (sum / (double)numbers.length));\n        \n        // 2. Binary Search Algorithm\n        int target = 60;\n        int index = binarySearch(numbers, target);\n        System.out.println(\"✓ Binary Search for \" + target + \" -> Found at Index: \" + index);\n    }\n    \n    private static int binarySearch(int[] arr, int target) {\n        int low = 0, high = arr.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (arr[mid] == target) return mid;\n            if (arr[mid] < target) low = mid + 1;\n            else high = mid - 1;\n        }\n        return -1;\n    }\n}','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:39:20','2026-08-25 03:09:20'),(273,0,0,1,NULL,'python','# 🐍 PYTHON 3.12 PRO STUDIO — EDUCATION ALGORITHM\nimport math\n\ndef generate_fibonacci(n):\n    sequence = [0, 1]\n    while len(sequence) < n:\n        sequence.append(sequence[-1] + sequence[-2])\n    return sequence\n\nprint(\"=========================================\")\nprint(\" 🐍 PYTHON 3.12 ALGORITHMIC EXECUTION\")\nprint(\"=========================================\")\n\nfib = generate_fibonacci(10)\nprint(f\"✓ First 10 Fibonacci Numbers: {fib}\")\n\nsquares = {x: x**2 for x in range(1, 6)}\nprint(f\"✓ Number Squares Dictionary: {squares}\")\nprint(\"🚀 Execution Completed Successfully!\")','# 🐍 PYTHON 3.12 PRO STUDIO — EDUCATION ALGORITHM\nimport math\n\ndef generate_fibonacci(n):\n    sequence = [0, 1]\n    while len(sequence) < n:\n        sequence.append(sequence[-1] + sequence[-2])\n    return sequence\n\nprint(\"=========================================\")\nprint(\" 🐍 PYTHON 3.12 ALGORITHMIC EXECUTION\")\nprint(\"=========================================\")\n\nfib = generate_fibonacci(10)\nprint(f\"✓ First 10 Fibonacci Numbers: {fib}\")\n\nsquares = {x: x**2 for x in range(1, 6)}\nprint(f\"✓ Number Squares Dictionary: {squares}\")\nprint(\"🚀 Execution Completed Successfully!\")','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:39:40','2026-08-25 03:09:40'),(274,0,0,1,NULL,'sql','SELECT c.title AS course_name, COUNT(e.id) AS total_enrolled_scholars, AVG(c.price) AS course_fee FROM courses c LEFT JOIN enrollments e ON c.id = e.course_id GROUP BY c.id, c.title ORDER BY total_enrolled_scholars DESC;','SELECT c.title AS course_name, COUNT(e.id) AS total_enrolled_scholars, AVG(c.price) AS course_fee FROM courses c LEFT JOIN enrollments e ON c.id = e.course_id GROUP BY c.id, c.title ORDER BY total_enrolled_scholars DESC;','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:40:11','2026-08-25 03:10:11'),(275,0,0,1,NULL,'java','public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Welcome to Code Arena Pro Studio!\");\n        int a = 15;\n        int b = 35;\n        System.out.println(\"Calculated Sum: \" + (a + b));\n    }\n}','public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Welcome to Code Arena Pro Studio!\");\n        int a = 15;\n        int b = 35;\n        System.out.println(\"Calculated Sum: \" + (a + b));\n    }\n}','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:4