d(sequence[-1] + sequence[-2])\n    return sequence\n\nprint(\"=========================================\")\nprint(\" 🐍 PYTHON 3.12 ALGORITHMIC EXECUTION\")\nprint(\"=========================================\")\n\nfib = generate_fibonacci(10)\nprint(f\"✓ First 10 Fibonacci Numbers: {fib}\")\n\nsquares = {x: x**2 for x in range(1, 6)}\nprint(f\"✓ Number Squares Dictionary: {squares}\")\nprint(\"🚀 Execution Completed Successfully!\")','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:45:12','2026-08-25 03:15:12'),(286,0,0,1,NULL,'java','public class Main {\n    public static int binarySearch(int[] arr, int target) {\n        int low = 0, high = arr.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (arr[mid] == target) return mid;\n            if (arr[mid] < target) low = mid + 1;\n            else high = mid - 1;\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        int[] data = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};\n        int target = 23;\n        int idx = binarySearch(data, target);\n        System.out.println(\"Java 21 Binary Search Executed Successfully!\");\n        System.out.println(\"Target: \" + target + \" -> Found at Index: \" + idx);\n    }\n}','public class Main {\n    public static int binarySearch(int[] arr, int target) {\n        int low = 0, high = arr.length - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (arr[mid] == target) return mid;\n            if (arr[mid] < target) low = mid + 1;\n            else high = mid - 1;\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        int[] data = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};\n        int target = 23;\n        int idx = binarySearch(data, target);\n        System.out.println(\"Java 21 Binary Search Executed Successfully!\");\n        System.out.println(\"Target: \" + target + \" -> Found at Index: \" + idx);\n    }\n}','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:46:11','2026-08-25 03:16:11'),(287,0,0,1,NULL,'python','def sieve_of_eratosthenes(limit):\n    primes = []\n    is_prime = [True] * (limit + 1)\n    for p in range(2, limit + 1):\n        if is_prime[p]:\n            primes.append(p)\n            for i in range(p * p, limit + 1, p):\n                is_prime[i] = False\n    return primes\n\nprint(\"==========================================\")\nprint(\"🐍 PYTHON 3.12 PRIME SIEVE BENCHMARK\")\nprint(\"==========================================\")\nprimes_up_to_30 = sieve_of_eratosthenes(30)\nprint(f\"✓ Primes up to 30: {primes_up_to_30}\")\nprint(\"🚀 Execution Completed Successfully!\")','def sieve_of_eratosthenes(limit):\n    primes = []\n    is_prime = [True] * (limit + 1)\n    for p in range(2, limit + 1):\n        if is_prime[p]:\n            primes.append(p)\n            for i in range(p * p, limit + 1, p):\n                is_prime[i] = False\n    return primes\n\nprint(\"==========================================\")\nprint(\"🐍 PYTHON 3.12 PRIME SIEVE BENCHMARK\")\nprint(\"==========================================\")\nprimes_up_to_30 = sieve_of_eratosthenes(30)\nprint(f\"✓ Primes up to 30: {primes_up_to_30}\")\nprint(\"🚀 Execution Completed Successfully!\")','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:46:14','2026-08-25 03:16:14'),(288,0,0,1,NULL,'cpp','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> numbers = {64, 25, 12, 22, 11, 90, 45};\n    sort(numbers.begin(), numbers.end());\n    \n    cout << \"==========================================\" << endl;\n    cout << \"C++ 20 Vector Sorting Engine\" << endl;\n    cout << \"==========================================\" << endl;\n    cout << \"Sorted Numbers: \";\n    for (int n : numbers) {\n        cout << n << \" \";\n    }\n    cout << endl << \"C++ Program Executed Successfully.\" << endl;\n    return 0;\n}','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> numbers = {64, 25, 12, 22, 11, 90, 45};\n    sort(numbers.begin(), numbers.end());\n    \n    cout << \"==========================================\" << endl;\n    cout << \"C++ 20 Vector Sorting Engine\" << endl;\n    cout << \"==========================================\" << endl;\n    cout << \"Sorted Numbers: \";\n    for (int n : numbers) {\n        cout << n << \" \";\n    }\n    cout << endl << \"C++ Program Executed Successfully.\" << endl;\n    return 0;\n}','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:46:17','2026-08-25 03:16:17'),(289,0,0,1,NULL,'javascript','const scholars = [\n    { name: \'Diana\', score: 95 },\n    { name: \'Bruce\', score: 88 },\n    { name: \'Clark\', score: 92 },\n    { name: \'Barry\', score: 78 }\n];\n\nconst topScholars = scholars\n    .filter(s => s.score >= 85)\n    .map(s => `Scholar: ${s.name} (Grade A: ${s.score}%)`);\n\nconsole.log(\"==========================================\");\nconsole.log(\"JavaScript Node.js Functional Execution\");\nconsole.log(\"==========================================\");\ntopScholars.forEach(line => console.log(line));\nconsole.log(\"JS Node.js Execution Completed Successfully.\");','const scholars = [\n    { name: \'Diana\', score: 95 },\n    { name: \'Bruce\', score: 88 },\n    { name: \'Clark\', score: 92 },\n    { name: \'Barry\', score: 78 }\n];\n\nconst topScholars = scholars\n    .filter(s => s.score >= 85)\n    .map(s => `Scholar: ${s.name} (Grade A: ${s.score}%)`);\n\nconsole.log(\"==========================================\");\nconsole.log(\"JavaScript Node.js Functional Execution\");\nconsole.log(\"==========================================\");\ntopScholars.forEach(line => console.log(line));\nconsole.log(\"JS Node.js Execution Completed Successfully.\");','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:46:21','2026-08-25 03:16:21'),(290,0,0,1,NULL,'sql','SELECT \n    c.title AS course_name,\n    COUNT(e.id) AS enrolled_students,\n    AVG(c.price) AS average_price\nFROM courses c\nLEFT JOIN enrollments e ON c.id = e.course_id\nGROUP BY c.id, c.title\nORDER BY enrolled_students DESC;','SELECT \n    c.title AS course_name,\n    COUNT(e.id) AS enrolled_students,\n    AVG(c.price) AS average_price\nFROM courses c\nLEFT JOIN enrollments e ON c.id = e.course_id\nGROUP BY c.id, c.title\nORDER BY enrolled_students DESC;','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:46:24','2026-08-25 03:16:24'),(291,0,0,1,NULL,'html','<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <style>\n        body { font-family: sans-serif; background: #0f172a; color: #fff; padding: 2rem; }\n        .card { background: linear-gradient(135deg, #6366f1, #a855f7); padding: 1.5rem; border-radius: 12px; }\n    </style>\n</head>\n<body>\n    <div class=\"card\">\n        <h2>Web Studio Live Card</h2>\n        <p>HTML5, CSS3 & JS Preview Rendered Successfully!</p>\n    </div>\n</body>\n</html>','<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <style>\n        body { font-family: sans-serif; background: #0f172a; color: #fff; padding: 2rem; }\n        .card { background: linear-gradient(135deg, #6366f1, #a855f7); padding: 1.5rem; border-radius: 12px; }\n    </style>\n</head>\n<body>\n    <div class=\"card\">\n        <h2>Web Studio Live Card</h2>\n        <p>HTML5, CSS3 & JS Preview Rendered Successfully!</p>\n    </div>\n</body>\n</html>','WEB_RUNNER_UNAVAILABLE','WEB_RUNNER_UNAVAILABLE',0,0,15,18400,0,0,'2026-08-24 21:46:26','2026-08-25 03:16:26'),(292,0,0,1,NULL,'java','import java.util.*;\n\npublic class Main {\n    static class Edge {\n        int target, weight;\n        Edge(int target, int weight) {\n            this.target = target;\n            this.weight = weight;\n        }\n    }\n\n    public static void main(String[] args) {\n        int numNodes = 5;\n        List<List<Edge>> graph = new ArrayList<>();\n        for (int i = 0; i < numNodes; i++) graph.add(new ArrayList<>());\n\n        // Graph edges: Source -> Target (Weight)\n        graph.get(0).add(new Edge(1, 4));\n        graph.get(0).add(new Edge(2, 2));\n        graph.get(1).add(new Edge(2, 1));\n        graph.get(1).add(new Edge(3, 5));\n        graph.get(2).add(new Edge(3, 8));\n        graph.get(2).add(new Edge(4, 10));\n        graph.get(3).add(new Edge(4, 2));\n\n        int[] dist = new int[numNodes];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        dist[0] = 0;\n\n        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));\n        pq.add(new int[]{0, 0});\n\n        while (!pq.isEmpty()) {\n            int[] curr = pq.poll();\n            int u = curr[0], d = curr[1];\n            if (d > dist[u]) continue;\n\n            for (Edge edge : graph.get(u)) {\n                if (dist[u] + edge.weight < dist[edge.target]) {\n                    dist[edge.target] = dist[u] + edge.weight;\n                    pq.add(new int[]{edge.target, dist[edge.target]});\n                }\n            }\n        }\n\n        System.out.println(\"Dijkstra Shortest Paths from Source Node 0:\");\n        for (int i = 0; i < numNodes; i++) {\n            System.out.println(\" -> Distance to Node \" + i + \": \" + dist[i]);\n        }\n    }\n}','import java.util.*;\n\npublic class Main {\n    static class Edge {\n        int target, weight;\n        Edge(int target, int weight) {\n            this.target = target;\n            this.weight = weight;\n        }\n    }\n\n    public static void main(String[] args) {\n        int numNodes = 5;\n        List<List<Edge>> graph = new ArrayList<>();\n        for (int i = 0; i < numNodes; i++) graph.add(new ArrayList<>());\n\n        // Graph edges: Source -> Target (Weight)\n        graph.get(0).add(new Edge(1, 4));\n        graph.get(0).add(new Edge(2, 2));\n        graph.get(1).add(new Edge(2, 1));\n        graph.get(1).add(new Edge(3, 5));\n        graph.get(2).add(new Edge(3, 8));\n        graph.get(2).add(new Edge(4, 10));\n        graph.get(3).add(new Edge(4, 2));\n\n        int[] dist = new int[numNodes];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        dist[0] = 0;\n\n        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));\n        pq.add(new int[]{0, 0});\n\n        while (!pq.isEmpty()) {\n            int[] curr = pq.poll();\n            int u = curr[0], d = curr[1];\n            if (d > dist[u]) continue;\n\n            for (Edge edge : graph.get(u)) {\n                if (dist[u] + edge.weight < dist[edge.target]) {\n                    dist[edge.target] = dist[u] + edge.weight;\n                    pq.add(new int[]{edge.target, dist[edge.target]});\n                }\n            }\n        }\n\n        System.out.println(\"Dijkstra Shortest Paths from Source Node 0:\");\n        for (int i = 0; i < numNodes; i++) {\n            System.out.println(\" -> Distance to Node \" + i + \": \" + dist[i]);\n        }\n    }\n}','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:47:16','2026-08-25 03:17:16'),(293,0,0,1,NULL,'python','def knapsack(weights, values, capacity):\n    n = len(values)\n    dp = [[0 for _ in range(capacity + 1)] for _ in range(n + 1)]\n\n    for i in range(1, n + 1):\n        for w in range(1, capacity + 1):\n            if weights[i - 1] <= w:\n                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])\n            else:\n                dp[i][w] = dp[i - 1][w]\n    \n    return dp[n][capacity]\n\nweights = [2, 3, 4, 5]\nvalues = [3, 4, 5, 6]\ncapacity = 5\n\nmax_val = knapsack(weights, values, capacity)\n\nprint(\"==========================================\")\nprint(\"🐍 DYNAMIC PROGRAMMING KNAPSACK BENCHMARK\")\nprint(\"==========================================\")\nprint(f\"🎒 Items Weights: {weights}\")\nprint(f\"💰 Items Values:  {values}\")\nprint(f\"⚡ Knapsack Capacity: {capacity}\")\nprint(f\"🏆 Maximum Achievable Value: {max_val}\")\nprint(\"🚀 Execution Completed Successfully!\")','def knapsack(weights, values, capacity):\n    n = len(values)\n    dp = [[0 for _ in range(capacity + 1)] for _ in range(n + 1)]\n\n    for i in range(1, n + 1):\n        for w in range(1, capacity + 1):\n            if weights[i - 1] <= w:\n                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])\n            else:\n                dp[i][w] = dp[i - 1][w]\n    \n    return dp[n][capacity]\n\nweights = [2, 3, 4, 5]\nvalues = [3, 4, 5, 6]\ncapacity = 5\n\nmax_val = knapsack(weights, values, capacity)\n\nprint(\"==========================================\")\nprint(\"🐍 DYNAMIC PROGRAMMING KNAPSACK BENCHMARK\")\nprint(\"==========================================\")\nprint(f\"🎒 Items Weights: {weights}\")\nprint(f\"💰 Items Values:  {values}\")\nprint(f\"⚡ Knapsack Capacity: {capacity}\")\nprint(f\"🏆 Maximum Achievable Value: {max_val}\")\nprint(\"🚀 Execution Completed Successfully!\")','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:47:19','2026-08-25 03:17:19'),(294,0,0,1,NULL,'cpp','#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\nNode* insert(Node* root, int val) {\n    if (!root) return new Node(val);\n    if (val < root->data) root->left = insert(root->left, val);\n    else root->right = insert(root->right, val);\n    return root;\n}\n\nvoid inorder(Node* root) {\n    if (!root) return;\n    inorder(root->left);\n    cout << root->data << \" \";\n    inorder(root->right);\n}\n\nint getHeight(Node* root) {\n    if (!root) return 0;\n    return 1 + max(getHeight(root->left), getHeight(root->right));\n}\n\nint main() {\n    Node* root = nullptr;\n    int values[] = {50, 30, 20, 40, 70, 60, 80};\n    for (int v : values) root = insert(root, v);\n\n    cout << \"==========================================\" << endl;\n    cout << \"C++ 20 Binary Search Tree Pointer Benchmark\" << endl;\n    cout << \"==========================================\" << endl;\n    cout << \"In-Order BST Traversal: \";\n    inorder(root);\n    cout << endl << \"Tree Height: \" << getHeight(root) << endl;\n    cout << \"C++ BST Execution Completed Successfully.\" << endl;\n    return 0;\n}','#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\nNode* insert(Node* root, int val) {\n    if (!root) return new Node(val);\n    if (val < root->data) root->left = insert(root->left, val);\n    else root->right = insert(root->right, val);\n    return root;\n}\n\nvoid inorder(Node* root) {\n    if (!root) return;\n    inorder(root->left);\n    cout << root->data << \" \";\n    inorder(root->right);\n}\n\nint getHeight(Node* root) {\n    if (!root) return 0;\n    return 1 + max(getHeight(root->left), getHeight(root->right));\n}\n\nint main() {\n    Node* root = nullptr;\n    int values[] = {50, 30, 20, 40, 70, 60, 80};\n    for (int v : values) root = insert(root, v);\n\n    cout << \"==========================================\" << endl;\n    cout << \"C++ 20 Binary Search Tree Pointer Benchmark\" << endl;\n    cout << \"==========================================\" << endl;\n    cout << \"In-Order BST Traversal: \";\n    inorder(root);\n    cout << endl << \"Tree Height: \" << getHeight(root) << endl;\n    cout << \"C++ BST Execution Completed Successfully.\" << endl;\n    return 0;\n}','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:47:22','2026-08-25 03:17:22'),(295,0,0,1,NULL,'javascript','class LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.cache = new Map();\n    }\n\n    get(key) {\n        if (!this.cache.has(key)) return -1;\n        const val = this.cache.get(key);\n        this.cache.delete(key);\n        this.cache.set(key, val);\n        return val;\n    }\n\n    put(key, value) {\n        if (this.cache.has(key)) {\n            this.cache.delete(key);\n        } else if (this.cache.size >= this.capacity) {\n            const oldestKey = this.cache.keys().next().value;\n            this.cache.delete(oldestKey);\n        }\n        this.cache.set(key, value);\n    }\n}\n\nconst lru = new LRUCache(2);\nlru.put(1, \'Course A\');\nlru.put(2, \'Course B\');\nconsole.log(\"Get Key 1:\", lru.get(1)); // returns Course A\nlru.put(3, \'Course C\');              // evicts key 2\nconsole.log(\"Get Key 2 (Evicted):\", lru.get(2)); // returns -1\nlru.put(4, \'Course D\');              // evicts key 1\nconsole.log(\"Get Key 1 (Evicted):\", lru.get(1)); // returns -1\nconsole.log(\"Get Key 3:\", lru.get(3)); // returns Course C\nconsole.log(\"Get Key 4:\", lru.get(4)); // returns Course D','class LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.cache = new Map();\n    }\n\n    get(key) {\n        if (!this.cache.has(key)) return -1;\n        const val = this.cache.get(key);\n        this.cache.delete(key);\n        this.cache.set(key, val);\n        return val;\n    }\n\n    put(key, value) {\n        if (this.cache.has(key)) {\n            this.cache.delete(key);\n        } else if (this.cache.size >= this.capacity) {\n            const oldestKey = this.cache.keys().next().value;\n            this.cache.delete(oldestKey);\n        }\n        this.cache.set(key, value);\n    }\n}\n\nconst lru = new LRUCache(2);\nlru.put(1, \'Course A\');\nlru.put(2, \'Course B\');\nconsole.log(\"Get Key 1:\", lru.get(1)); // returns Course A\nlru.put(3, \'Course C\');              // evicts key 2\nconsole.log(\"Get Key 2 (Evicted):\", lru.get(2)); // returns -1\nlru.put(4, \'Course D\');              // evicts key 1\nconsole.log(\"Get Key 1 (Evicted):\", lru.get(1)); // returns -1\nconsole.log(\"Get Key 3:\", lru.get(3)); // returns Course C\nconsole.log(\"Get Key 4:\", lru.get(4)); // returns Course D','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:47:26','2026-08-25 03:17:26'),(296,0,0,1,NULL,'sql','SELECT \n    c.title AS course_title,\n    c.price AS list_price,\n    COUNT(e.id) AS total_enrolled,\n    CASE \n        WHEN COUNT(e.id) >= 2 THEN \'🔥 BEST SELLER\'\n        WHEN COUNT(e.id) = 1 THEN \'📈 POPULAR\'\n        ELSE \'🆕 NEW COHORT\'\n    END AS tier_status,\n    ROUND(c.price * 0.85, 2) AS discounted_fee\nFROM courses c\nLEFT JOIN enrollments e ON c.id = e.course_id\nGROUP BY c.id, c.title, c.price\nORDER BY total_enrolled DESC, list_price DESC;','SELECT \n    c.title AS course_title,\n    c.price AS list_price,\n    COUNT(e.id) AS total_enrolled,\n    CASE \n        WHEN COUNT(e.id) >= 2 THEN \'🔥 BEST SELLER\'\n        WHEN COUNT(e.id) = 1 THEN \'📈 POPULAR\'\n        ELSE \'🆕 NEW COHORT\'\n    END AS tier_status,\n    ROUND(c.price * 0.85, 2) AS discounted_fee\nFROM courses c\nLEFT JOIN enrollments e ON c.id = e.course_id\nGROUP BY c.id, c.title, c.price\nORDER BY total_enrolled DESC, list_price DESC;','QUEUED','QUEUED',0,0,0,0,0,0,'2026-08-24 21:47:29','2026-08-25 03:17:29'),(297,0,0,1,NULL,'html','<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <style>\n        body { font-family: \'Inter\', sans-serif; background: #090d16; color: #fff; padding: 2rem; display: flex; justify-content: center; }\n        .glass-card {\n            background: rgba(255, 255, 255, 0.05);\n            backdrop-filter: blur(12px);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n            border-radius: 16px;\n            padding: 2rem;\n            max-width: 400px;\n            box-shadow: 0 8px 32px rgba(0,0,0,0.37);\n        }\n        .btn { background: #6366f1; color: #fff; border: none; padding: 0.75rem 1.5rem; border-radius: 8px; font-weight: 700; cursor: pointer; }\n    </style>\n</head>\n<body>\n    <div class=\"glass-card\">\n        <h3>⚡ Full Stack AI Engineering</h3>\n        <p>Master Java 21, Python GenAI, Microservices & Cloud Infrastructure.</p>\n        <button class=\"btn\">Enroll Now &rarr;</button>\n    <