  String status;\n        String deadline;\n\n        Task(int id, String name, String status, String deadline) {\n            this.id = id;\n            this.name = name;\n            this.status = status;\n            this.deadline = deadline;\n        }\n    }\n\n    static ArrayList<Task> tasks = new ArrayList<>();\n    static Scanner scanner = new Scanner(System.in);\n\n    public static void main(String[] args) {\n\n        // Pre-populated sample tasks for demo execution\n        tasks.add(new Task(1, \"Java Assignment\", \"Completed\", \"05-09-2026\"));\n        tasks.add(new Task(2, \"DBMS Project\", \"Pending\", \"10-09-2026\"));\n        tasks.add(new Task(3, \"Lab Record\", \"In Progress\", \"15-09-2026\"));\n        tasks.add(new Task(4, \"Hackathon\", \"Upcoming\", \"20-09-2026\"));\n\n        System.out.println(\"==========================================\");\n        System.out.println(\"       STUDENT TASK TRACKER\");\n        System.out.println(\"==========================================\");\n\n        while (scanner.hasNext()) {\n            showMenu();\n\n            System.out.print(\"Choose an option: \");\n            Integer choice = readInteger();\n            if (choice == null) break; // Exit gracefully if input finishes (EOF)\n\n            switch (choice) {\n                case 1:\n                    viewAllTasks();\n                    break;\n\n                case 2:\n                    addTask();\n                    break;\n\n                case 3:\n                    markTaskCompleted();\n                    break;\n\n                case 4:\n                    viewPendingTasks();\n                    break;\n\n                case 5:\n                    System.out.println(\"\\nThank you for using Student Task Tracker!\");\n                    System.out.println(\"Keep learning, keep building!\");\n                    return;\n\n                default:\n                    System.out.println(\"Invalid option. Please choose 1-5.\");\n            }\n        }\n\n        // Default automated view if no menu choice provided in Custom Input\n        if (tasks.size() > 0) {\n            viewAllTasks();\n        }\n    }\n\n    static void showMenu() {\n        System.out.println(\"\\n==========================================\");\n        System.out.println(\"               MAIN MENU\");\n        System.out.println(\"==========================================\");\n        System.out.println(\"1. View All Tasks\");\n        System.out.println(\"2. Add New Task\");\n        System.out.println(\"3. Mark Task as Completed\");\n        System.out.println(\"4. View Pending Tasks\");\n        System.out.println(\"5. Exit\");\n        System.out.println(\"==========================================\");\n    }\n\n    static void viewAllTasks() {\n        System.out.println(\"\\n---------------- ALL TASKS ----------------\");\n\n        if (tasks.isEmpty()) {\n            System.out.println(\"No tasks available.\");\n            return;\n        }\n\n        System.out.printf(\"%-5s %-25s %-15s %-15s%n\", \"ID\", \"TASK\", \"STATUS\", \"DEADLINE\");\n        System.out.println(\"------------------------------------------------------------\");\n\n        for (Task task : tasks) {\n            System.out.printf(\"%-5d %-25s %-15s %-15s%n\", task.id, task.name, task.status, task.deadline);\n        }\n    }\n\n    static void addTask() {\n        System.out.println(\"\\n------------- ADD NEW TASK -------------\");\n\n        System.out.print(\"Enter task name: \");\n        if (!scanner.hasNextLine()) return;\n        String name = scanner.nextLine();\n\n        System.out.print(\"Enter deadline: \");\n        if (!scanner.hasNextLine()) return;\n        String deadline = scanner.nextLine();\n\n        System.out.println(\"\\nChoose status: 1. Pending | 2. In Progress | 3. Upcoming\");\n        Integer statusChoice = readInteger();\n        if (statusChoice == null) statusChoice = 1;\n\n        String status;\n        switch (statusChoice) {\n            case 1: status = \"Pending\"; break;\n            case 2: status = \"In Progress\"; break;\n            case 3: status = \"Upcoming\"; break;\n            default: status = \"Pending\";\n        }\n\n        int newId = tasks.size() + 1;\n        tasks.add(new Task(newId, name, status, deadline));\n        System.out.println(\"\\nTask added successfully!\");\n    }\n\n    static void markTaskCompleted() {\n        System.out.println(\"\\n--------- MARK TASK COMPLETED ---------\");\n        viewAllTasks();\n\n        System.out.print(\"\\nEnter Task ID: \");\n        Integer id = readInteger();\n        if (id == null) return;\n\n        boolean found = false;\n        for (Task task : tasks) {\n            if (task.id == id) {\n                task.status = \"Completed\";\n                System.out.println(\"\\nTask marked as completed!\");\n                found = true;\n                break;\n            }\n        }\n\n        if (!found) {\n            System.out.println(\"Task ID not found.\");\n        }\n    }\n\n    static void viewPendingTasks() {\n        System.out.println(\"\\n------------ PENDING TASKS ------------\");\n        boolean found = false;\n\n        for (Task task : tasks) {\n            if (!task.status.equals(\"Completed\")) {\n                System.out.println(task.id + \". \" + task.name + \" | \" + task.status + \" | Deadline: \" + task.deadline);\n                found = true;\n            }\n        }\n\n        if (!found) {\n            System.out.println(\"No pending tasks!\");\n        }\n    }\n\n    // Safe Integer input reader with End-Of-File (EOF) protection\n    static Integer readInteger() {\n        if (!scanner.hasNext()) return null;\n        \n        while (scanner.hasNext() && !scanner.hasNextInt()) {\n            scanner.next(); // Skip invalid token\n        }\n\n        if (!scanner.hasNextInt()) return null;\n\n        int value = scanner.nextInt();\n        